import { artworks } from './artworks.js';
const $=s=>document.querySelector(s),viewport=$('#viewport'),panel=$('#analysis'),scrim=$('#scrim'),instruction=$('#instruction');
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x)),lerp=(a,b,t)=>a+(b-a)*t, ease=t=>{t=clamp(t,0,1);return t*t*(3-2*t)};
let THREE,scene,camera,renderer,clock,frames=[],clickTargets=[],active=-1,phase='idle',start=0,raf=0,visible=true,look=0,lookTarget=0,drag=null,lastFocus=null;
const flight=reduced?80:1100;
function fill(i){const a=artworks[i];const fields={'#analysis-number':`${String(i+1).padStart(2,'0')} / 03`,'#analysis-theme':a.theme,'#analysis-title':a.title,'#analysis-subtitle':a.subtitle,'#analysis-creator':a.creator,'#analysis-description':a.description,'#analysis-reflection':a.reflection,'#analysis-concepts':a.concepts,'#analysis-connection':a.connection};for(const [s,v] of Object.entries(fields))$(s).textContent=v;}
function updateTabs(){document.querySelectorAll('[data-i]').forEach(b=>b.classList.toggle('active',+b.dataset.i===active));}
function open(i){if(phase!=='idle')return;lastFocus=document.activeElement;active=i;fill(i);updateTabs();phase='approach';start=performance.now();scrim.classList.add('open');instruction.textContent='A NEW PERSPECTIVE IS UNFOLDING';}
function close(){if(phase!=='reading')return;panel.classList.remove('open');panel.setAttribute('aria-hidden','true');phase='return';start=performance.now();instruction.textContent='RETURNING TO THE GALLERY';}
function switchTo(i){if(phase!=='reading')return;fill(i);active=i;updateTabs();frames.forEach((f,j)=>{f.group.visible=j===i;f.group.position.set(j===i?-1.4:f.home.x,0,j===i?3.8:f.home.z);f.group.rotation.y=j===i?-.95:0;});panel.classList.remove('open');void panel.offsetWidth;panel.classList.add('open');$('#close').focus({preventScroll:true});}
$('#close').addEventListener('click',close);$('#prev').addEventListener('click',()=>switchTo((active+2)%3));$('#next').addEventListener('click',()=>switchTo((active+1)%3));scrim.addEventListener('click',close);document.querySelectorAll('[data-i]').forEach(b=>b.addEventListener('click',()=>open(+b.dataset.i)));
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(phase==='idle'&&['1','2','3'].includes(e.key))open(Number(e.key)-1);if(phase==='reading'&&e.key==='Tab'){const focusable=[...panel.querySelectorAll('button')];if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0].focus()}}});
function material(color,metalness=.1,roughness=.5){return new THREE.MeshStandardMaterial({color,metalness,roughness})}
function box(parent,w,h,d,x,y,z,mat){const mesh=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);mesh.position.set(x,y,z);parent.add(mesh);return mesh}
function line(parent,pts,color,opacity=.5){const geo=new THREE.BufferGeometry().setFromPoints(pts.map(p=>new THREE.Vector3(...p)));const m=new THREE.Line(geo,new THREE.LineBasicMaterial({color,transparent:true,opacity}));parent.add(m);return m}
function makeTextTexture(i){const c=document.createElement('canvas');c.width=512;c.height=768;const g=c.getContext('2d');g.fillStyle='#06101f';g.fillRect(0,0,512,768);const grd=g.createRadialGradient(256,310,10,256,350,370);grd.addColorStop(0,'#1b3352');grd.addColorStop(1,'#030712');g.fillStyle=grd;g.fillRect(0,0,512,768);g.strokeStyle='#729fce';g.lineWidth=2;g.strokeRect(25,25,462,718);g.fillStyle='#9ecbff';g.font='13px Arial';g.textAlign='center';g.fillText('ORIGINAL ARTWORK PLACEHOLDER',256,700);g.font='12px Arial';g.fillStyle='#809dbb';g.fillText('REPLACE WITH YOUR OWN ART',256,725);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;return t}
function makeSculpture(i,container){const cyan=material(0x70c3ff,.65,.2),blue=material(0x264f86,.55,.26),silver=material(0xb5d9ff,.75,.18);const glow=new THREE.MeshBasicMaterial({color:0x8bd0ff});const art=new THREE.Group();container.add(art);
if(i===0){const core=new THREE.Mesh(new THREE.IcosahedronGeometry(.74,1),blue);art.add(core);const ring1=new THREE.Mesh(new THREE.TorusGeometry(1.05,.024,8,90),cyan);ring1.rotation.x=.48;art.add(ring1);const ring2=new THREE.Mesh(new THREE.TorusGeometry(.91,.014,8,90),silver);ring2.rotation.y=1.13;art.add(ring2);const spike=new THREE.Mesh(new THREE.OctahedronGeometry(.32),silver);spike.position.y=.1;art.add(spike);art.userData.animate=t=>{ring1.rotation.z=t*.16;ring2.rotation.x=t*.12;core.rotation.y=t*.1}}
else if(i===1){const mesh=new THREE.Mesh(new THREE.IcosahedronGeometry(.94,2),new THREE.MeshStandardMaterial({color:0x234b79,wireframe:true,transparent:true,opacity:.8}));art.add(mesh);const solid=new THREE.Mesh(new THREE.IcosahedronGeometry(.65,1),blue);art.add(solid);for(let k=0;k<3;k++){const ring=new THREE.Mesh(new THREE.TorusGeometry(1.05+k*.19,.012,6,100),cyan);ring.rotation.set(.6+k*.38,.4+k*.7,.1+k*.5);art.add(ring)}art.userData.animate=t=>{mesh.rotation.y=t*.09;solid.rotation.x=t*.14;art.rotation.y=t*.055}}
else{const pts=[[-.78,.7,0],[.7,.75,0],[-.85,-.6,0],[.82,-.55,0],[0,.05,.5],[0,-.05,-.4]];for(const [a,b] of [[0,1],[0,2],[1,3],[2,3],[0,4],[1,4],[2,4],[3,4],[4,5],[0,5],[3,5]])line(art,[pts[a],pts[b]],0x8dcaff,.85);for(const p of pts){const node=new THREE.Mesh(new THREE.IcosahedronGeometry(.13,1),silver);node.position.set(...p);art.add(node)}const center=new THREE.Mesh(new THREE.OctahedronGeometry(.3),blue);art.add(center);art.userData.animate=t=>{art.rotation.y=Math.sin(t*.22)*.25;center.rotation.z=t*.3}}
art.scale.setScalar(.94);return art}
function makeFrame(i){const group=new THREE.Group();scene.add(group);const backing=material(0x081322,.32,.4),trim=material(0x4a789e,.82,.22),edge=material(0x9ac8e8,.8,.25);const width=2.7,height=3.6;box(group,width+.2,height+.2,.19,0,0,-.2,backing);for(const [x,y,w,h] of [[0,1.83,2.88,.065],[0,-1.83,2.88,.065],[-1.39,0,.065,3.7],[1.39,0,.065,3.7]])box(group,w,h,.16,x,y,.07,trim);for(const [x,y,w,h] of [[0,1.69,2.55,.012],[0,-1.69,2.55,.012],[-1.25,0,.012,3.35],[1.25,0,.012,3.35]])box(group,w,h,.02,x,y,.15,edge);
const tex=makeTextTexture(i);const artmat=new THREE.MeshStandardMaterial({map:tex,metalness:.08,roughness:.75,side:THREE.DoubleSide});const surface=new THREE.Mesh(new THREE.PlaneGeometry(2.46,3.32),artmat);surface.position.z=.14;group.add(surface);surface.userData.index=i;clickTargets.push(surface);
const sculpture=makeSculpture(i,group);sculpture.position.z=.5;
if(artworks[i].image){new THREE.TextureLoader().load(artworks[i].image,texture=>{texture.colorSpace=THREE.SRGBColorSpace;surface.material.map=texture;surface.material.needsUpdate=true;sculpture.visible=false;tex.dispose()},undefined,()=>console.warn('Missing original artwork:',artworks[i].image))}
const spot=new THREE.SpotLight(0x8bbfff,30,13,Math.PI/5,.75,1.3);spot.position.set(0,3.6,4.5);spot.target.position.set(0,0,0);group.add(spot,spot.target);
const home=new THREE.Vector3((i-1)*4.15,-.32,-5.3-Math.abs(i-1)*1.4);group.position.copy(home);return {group,home,sculpture,spot,tex};}
function hall(){scene.fog=new THREE.FogExp2(0x030712,.022);const dark=material(0x060b15,.25,.72),floorMat=material(0x07101d,.58,.26),beam=material(0x173353,.7,.3),accent=new THREE.MeshBasicMaterial({color:0x366c9e,transparent:true,opacity:.48});const floor=new THREE.Mesh(new THREE.PlaneGeometry(150,160),floorMat);floor.rotation.x=-Math.PI/2;floor.position.y=-3.35;scene.add(floor);const ceiling=new THREE.Mesh(new THREE.PlaneGeometry(150,160),dark);ceiling.rotation.x=Math.PI/2;ceiling.position.y=5.5;scene.add(ceiling);for(const x of [-8.8,8.8]){const wall=new THREE.Mesh(new THREE.PlaneGeometry(160,16),dark);wall.rotation.y=Math.PI/2;wall.position.set(x,1,-35);scene.add(wall)}
for(let z=3;z>-85;z-=9){for(const x of [-8.1,8.1]){box(scene,.08,8,.1,x,.7,z,beam);box(scene,.12,.04,8.6,x,-3.25,z-4.3,accent)}box(scene,16.3,.07,.08,0,5.1,z,beam);const p=new THREE.PointLight(0x31649e,3,15);p.position.set(0,4.4,z);scene.add(p)}
for(let j=0;j<19;j++){const z=3-j*4.5;line(scene,[[-7.9,-3.32,z],[7.9,-3.32,z]],0x38679d,.26);line(scene,[[0,-3.32,z],[0,-3.32,z-3.5]],0x4a87c6,.25)}
// Geometric architectural depth: illuminated nested frames, not a flat backdrop.
for(let k=0;k<7;k++){const z=-11-k*11;const w=7.8-k*.3,h=4.3-k*.08;line(scene,[[-w,-2.9,z],[-w,h,z],[w,h,z],[w,-2.9,z]],0x3c78b5,.21)}
const dustGeo=new THREE.BufferGeometry(),pos=[];for(let k=0;k<160;k++)pos.push((Math.random()-.5)*19,(Math.random()-.5)*9,-Math.random()*70+5);dustGeo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));const dust=new THREE.Points(dustGeo,new THREE.PointsMaterial({color:0x83bfff,size:.035,transparent:true,opacity:.5,sizeAttenuation:true}));scene.add(dust)}
function fallback(error){console.error('Museum fallback:',error);$('#museum').classList.add('no-webgl');$('#fallback').hidden=false;artworks.forEach((a,i)=>{const b=document.createElement('button');b.textContent=a.title;b.onclick=()=>{active=i;fill(i);phase='reading';scrim.classList.add('open');panel.classList.add('open');panel.setAttribute('aria-hidden','false')};$('#fallback-buttons').appendChild(b)})}
async function init(){try{THREE=await import('https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js');scene=new THREE.Scene();scene.background=new THREE.Color(0x030610);camera=new THREE.PerspectiveCamera(48,1,.1,150);camera.position.set(0,.1,12.4);renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.5));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.5;viewport.appendChild(renderer.domElement);scene.add(new THREE.AmbientLight(0x7495bb,.65));hall();frames=artworks.map((_,i)=>makeFrame(i));clock=new THREE.Clock();const resize=()=>{const w=viewport.clientWidth,h=viewport.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.fov=w<720?70:48;camera.updateProjectionMatrix()};resize();const ro=new ResizeObserver(resize);ro.observe(viewport);
const ray=new THREE.Raycaster(),point=new THREE.Vector2();viewport.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,dist:0}});viewport.addEventListener('pointermove',e=>{if(drag){drag.dist+=Math.abs(e.clientX-drag.x)+Math.abs(e.clientY-drag.y);lookTarget=clamp(lookTarget+(e.clientX-drag.x)*.0007,-.22,.22);drag.x=e.clientX;drag.y=e.clientY}else if(!reduced){const r=viewport.getBoundingClientRect();lookTarget=clamp(((e.clientX-r.left)/r.width-.5)*.23,-.17,.17)}});viewport.addEventListener('pointerup',e=>{if(!drag)return;const moved=drag.dist;drag=null;if(moved>12||phase!=='idle')return;const r=viewport.getBoundingClientRect();point.set(((e.clientX-r.left)/r.width)*2-1,-((e.clientY-r.top)/r.height)*2+1);ray.setFromCamera(point,camera);const hit=ray.intersectObjects(clickTargets)[0];if(hit)open(hit.object.userData.index)});viewport.addEventListener('pointercancel',()=>drag=null);
const io=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible&&!raf)animate()});io.observe(viewport);document.addEventListener('visibilitychange',()=>{visible=!document.hidden;if(visible&&!raf)animate()});window.addEventListener('pagehide',()=>{cancelAnimationFrame(raf);io.disconnect();ro.disconnect();frames.forEach(f=>f.tex.dispose());renderer.dispose()},{once:true});animate();}catch(err){fallback(err)}}
function animate(){if(!renderer||!visible||document.hidden){raf=0;return}raf=requestAnimationFrame(animate);const now=performance.now(),t=clock.getElapsedTime();look=lerp(look,lookTarget,.05);let camX=look*4,camZ=12.4;
const progress=phase==='approach'?ease((now-start)/flight):phase==='return'?1-ease((now-start)/flight):phase==='reading'?1:0;
frames.forEach((f,i)=>{const isActive=i===active,p=isActive?progress:0;f.group.position.x=lerp(f.home.x,-1.35,p);f.group.position.y=lerp(f.home.y+(reduced?0:Math.sin(t*.58+i*1.5)*.09),-.1,p);f.group.position.z=lerp(f.home.z,4.3,p);f.group.rotation.y=lerp(0,-1.08,p);f.group.rotation.z=lerp(0,-.055,p);f.spot.intensity=lerp(30,55,p);f.group.visible=active===-1||isActive||phase==='approach'&&p<.7||phase==='return';if(!reduced&&f.sculpture.visible)f.sculpture.userData.animate?.(t)});
if(active>=0){camX=lerp(camX,-.25,progress);camZ=lerp(12.4,10.3,progress);if(phase==='approach'&&now-start>=flight){phase='reading';panel.classList.add('open');panel.setAttribute('aria-hidden','false');$('#close').focus({preventScroll:true})}if(phase==='return'&&now-start>=flight){phase='idle';active=-1;updateTabs();scrim.classList.remove('open');instruction.innerHTML='<span class="pulse"></span> SELECT AN ARTWORK TO EXPLORE <span class="separator">·</span> DRAG TO SHIFT PERSPECTIVE';lastFocus?.focus?.({preventScroll:true})}}
camera.position.x=lerp(camera.position.x,camX,.055);camera.position.z=lerp(camera.position.z,camZ,.055);camera.lookAt(0,-.15,-5.5);renderer.render(scene,camera)}
init();
